#include <vector>
#include <algorithm>

class Solution {
public:
    long long maxScore(std::vector<int>& a, std::vector<int>& b) {
        long long INF = 1e18;
        std::vector<long long> dp(5, -INF);
        dp[0] = 0;

        for (int x : b) {
            for (int j = 3; j >= 0; --j) {
                if (dp[j] != -INF) {
                    dp[j + 1] = std::max(dp[j + 1], dp[j] + (long long)a[j] * x);
                }
            }
        }
        return dp[4];
    }
};

import java.util.Arrays;

class Solution {
    public long maxScore(int[] a, int[] b) {
        long INF = (long) 1e18;
        long[] dp = new long[5];
        Arrays.fill(dp, -INF);
        dp[0] = 0;

        for (int x : b) {
            for (int j = 3; j >= 0; j--) {
                if (dp[j] != -INF) {
                    dp[j + 1] = Math.max(dp[j + 1], dp[j] + (long) a[j] * x);
                }
            }
        }
        return dp[4];
    }
}

var maxScore = function(a, b) {
    const INF = 1e16;
    const dp = [-0, -INF, -INF, -INF, -INF];

    for (const x of b) {
        for (let j = 3; j >= 0; j--) {
            if (dp[j] !== -INF) {
                const cand = dp[j] + a[j] * x;
                if (cand > dp[j + 1]) dp[j + 1] = cand;
            }
        }
    }
    return dp[4];
};
